class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.3.0/commando_0.3.0_darwin_arm64.tar.gz"
      sha256 "d9245de237e4b6a4ef55903764111c7f148ce0356c65af966b3645fe17ac7600"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.3.0/commando_0.3.0_darwin_amd64.tar.gz"
      sha256 "84a748bcdc6b12715593c0379d1aa269578ba91009c0dcab3d227dd7aa404b21"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.3.0/commando_0.3.0_linux_arm64.tar.gz"
      sha256 "0787830d1bcee20c7a35044a43602efa03e1f069e5d8ee4b2f31bd7ea3b74895"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.3.0/commando_0.3.0_linux_amd64.tar.gz"
      sha256 "129369c4beecbcecf7bd50430ded8083575e5ee54ab825b9d5f6e04a9f007580"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
